import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        matrix = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(int(next(iterator)))
            matrix.append(row)

        ops = 0
        current_transpose_count = 0

        for L in range(N, 0, -1):
            target_row = L - 1
            target_col = L - 1

            r, c = target_row, target_col

            if current_transpose_count % 2 == 1:
                r, c = c, r

            val = matrix[r][c]
            expected_val = L * L

            if val != expected_val:
                ops += 1
                current_transpose_count += 1

        results.append(str(ops))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
